from common import *
R = 'f1-frontend'
T = []

# ---------------------------------------------------------------- 344 virtualization
T.append(topic(344, 'list-virtualization', R, 24, 'Rendering Huge Lists: Virtualization',
 ['Explain why rendering every row of a long list is slow',
  'Render only the visible window of rows plus a small overscan',
  'Handle variable row heights, scroll position, search and accessibility'],
 3, 11, [201],
 [text(344, 1, 'Ten thousand rows, twenty on screen',
   'A list of 10,000 rows with 8 elements each creates 80,000 elements, yet only about 20 rows fit on screen. Every element costs memory, style and layout work, so the page loads slowly and scrolls badly. Virtualization renders only the rows near the viewport and reuses them as the user scrolls.',
   ['dom-size']),
  text(344, 2, 'Worked example: the window',
   'Rows are 48 px tall and the viewport is 800 px, so 17 rows are visible. Adding 5 rows of overscan above and below gives 27 rendered rows, and 27 × 8 = 216 elements instead of 80,000. A tall spacer keeps the scrollbar the size of the full list, and the rows move to wherever the user has scrolled.',
   ['windowing']),
  diagram(344, 3, 'How a virtual list renders', 'Turn the scroll position into a range of rows.', ['windowing'],
   ['Read the scroll offset of the list container', 'First row = offset ÷ row height, minus the overscan', 'Last row = first row + rows that fit, plus the overscan', 'Render only those rows, positioned at their offsets', 'A spacer keeps the full height so the scrollbar is right']),
  text(344, 4, 'Variable heights and lighter options',
   'If rows differ in height, estimate them, measure each row once it renders, and correct the offsets. For long pages of mostly static content, the content-visibility property can let the browser skip rendering work for sections far off screen without removing them, a lighter step than full virtualization.',
   ['variable-heights']),
  text(344, 5, 'Trap: losing find-in-page and screen readers',
   'Rows that are not rendered cannot be found with the browser’s find-in-page or read by assistive technology. Provide your own search, keep the list’s total size and each row’s position available to assistive technology, and do not virtualize short lists that would render fine.',
   ['accessibility'])],
 [mc('t344-a1', 'dom-size', 'A table renders 5,000 rows with 10 elements each. What is the main cost?',
   [('a', 'Network time to download all of the row data first'), ('b', 'About 50,000 elements to style, lay out and hold'), ('c', 'The database query that produces the rows'), ('d', 'Decoding the icon images shown in the rows')], 'b',
   'The element count drives style, layout and memory work in the browser.'),
  mc('t344-a2', 'windowing', 'What does a virtual list render?',
   [('a', 'The rows in the viewport plus a few above and below'), ('b', 'All of the rows, with off-screen ones hidden by styles'), ('c', 'The first 100 rows, then a “load more” button'), ('d', 'One row at a time as the user taps')], 'a',
   'A window of visible rows plus overscan, recalculated on scroll.'),
  mc('t344-a3', 'windowing', 'Why add overscan rows outside the viewport?',
   [('a', 'To keep the scrollbar thumb the right size for the list'), ('b', 'To help search engines index the list'), ('c', 'So fast scrolling shows rows instead of blank space'), ('d', 'To reduce the number of elements rendered')], 'c',
   'Overscan hides the gap while new rows render during fast scrolls.'),
  mc('t344-a4', 'accessibility', 'What is a real drawback of virtualizing a list?',
   [('a', 'The scrollbar size can no longer match the length of the list'), ('b', 'Rows can no longer contain links'), ('c', 'Images in rows stop loading lazily'), ('d', 'Find-in-page and assistive technology miss rows not rendered')], 'd',
   'Unrendered rows are not in the document, so provide search and position information yourself.'),
  order('t344-a5', 'windowing', 'Order what happens on each scroll in a virtual list.',
   ['Read the scroll offset', 'Compute the first and last rows, with overscan', 'Render or reuse elements for those rows', 'Position them at their offsets inside the spacer'],
   ['s3', 's1', 's4', 's2'], 'Offset to range, range to elements, elements to positions.'),
  est('t344-a6', 'windowing', 'Rows are 48 px, the viewport is 800 px and overscan is 5 rows on each side. About how many rows does a virtual list render?', 'rows', 27,
   ['Row heights are fixed', 'Visible rows round up'], '800 ÷ 48, rounded up, plus 10', '17 visible + 10 overscan = 27 rows',
   'Sanity check: a few dozen rows whatever the list length.', 0.1, [10000, 17])],
 flash(344, [('Why virtualize?', 'Elements cost style, layout and memory; render only what is near the viewport.'),
             ('What keeps the scrollbar right?', 'A spacer as tall as the full list.'),
             ('Main drawback?', 'Find-in-page and assistive technology miss unrendered rows.')]),
 src([('Chrome for Developers: Avoid an excessive DOM size', 'https://developer.chrome.com/docs/lighthouse/performance/dom-size'),
      ('web.dev: content-visibility', 'https://web.dev/articles/content-visibility')]),
 deep(['dom-size', 'windowing', 'variable-heights', 'accessibility'], 'How a virtual list keeps the element count fixed',
  ['Every element on the page has a cost. The browser matches style rules against it, computes its layout box, and keeps it in memory; changes near the top of a long list can force layout of everything after. Lighthouse’s guidance flags pages with very large element counts because they slow loading, interaction and memory.',
   'A virtual list keeps a scroll container whose inner spacer is as tall as all rows together, so the scrollbar behaves as if every row existed. On scroll, it reads the offset, works out which rows intersect the viewport, and renders only those, plus some overscan above and below.',
   'Rendered rows are positioned at their offsets inside the spacer, usually with a transform or absolute positioning. Elements leaving the window are reused for rows entering it, so the number of elements stays roughly constant however long the list grows. Reuse also avoids creating and discarding thousands of elements during a long, fast scroll.',
   'Variable row heights need a model of offsets. A list starts with estimated heights, measures rows after they render, and updates the offsets of rows below. Keeping the scroll position anchored to the row the user is reading avoids jumps when estimates are corrected.',
   'Accessibility and search need explicit work. Rows outside the window are absent from the document, so find-in-page misses them and assistive technology cannot count them. Lists can expose their total size and each row’s position with ARIA attributes, keep focus on a rendered row, and offer an in-app search. Printing and copying a whole selection need the same care, since only rendered rows can be printed or selected.'],
  ['Lists, tables and feeds with thousands of rows or more.', 'Long chat histories and logs that grow while open.'],
  ['Avoid for short lists that render well as they are.', 'Avoid when users rely on find-in-page and you cannot provide search.'],
  ['Approach', 'Element count', 'Cost'],
  [['Render every row', 'Grows with the list', 'Slow load and scroll on long lists'],
   ['Pagination', 'One page of rows', 'Users click through pages'],
   ['Virtualization', 'Roughly fixed', 'Complexity, search and accessibility work']],
  'Elements with and without a window',
  ['10,000 rows, 8 elements each', 'Rows 48 px, viewport 800 px', 'Overscan 5 rows each side'],
  ['Render every row: 10,000 × 8 = 80,000 elements.', 'Visible rows: 800 ÷ 48 rounds up to 17.', 'Rendered rows: 17 + 10 = 27.', 'Virtualized: 27 × 8 = 216 elements.'],
  'The virtual list renders a few hundred elements whether the list holds a thousand rows or a million.',
  'What the tools report', 'Official documentation',
  'Chrome’s Lighthouse documentation for the excessive DOM size audit says it warns when a page’s body has more than about 800 elements and errors above about 1,400, and explains that a large DOM increases memory use, style calculation and layout cost. web.dev documents the content-visibility property, which lets the browser skip rendering work for off-screen content.',
  [('“The browser only paints what’s on screen, so 80,000 rows is fine.”', '“Style, layout and memory still scale with every element; I’d render a window.”'),
   ('“Virtualize every list.”', '“Only long ones; it costs find-in-page and needs accessibility work.”')],
  ['Element count drives style, layout and memory cost.', 'Render the visible window plus overscan inside a full-height spacer.', 'Measure variable rows and anchor the scroll position.', 'Restore search and accessibility that unrendered rows lose.']),
 {"kind": "slider", "title": "How many elements?", "prompt": "Rows are 48 px tall with 8 elements each, the viewport is 800 px and the list renders 5 extra rows above and below. Slide the list length and compare rendering every row with a virtual list.",
  "model": "virtual-list", "params": {"rowPx": 48, "viewportPx": 800, "overscan": 5, "nodesPerRow": 8, "domBudget": 1400},
  "control": {"label": "Rows in the list", "min": 50, "max": 20000, "step": 50, "initial": 1000, "unit": ""},
  "takeaway": "Rendering every row passes the 1,400 elements Lighthouse flags at fewer than 200 rows; the virtual list stays at 216 elements however long the list grows."},
 see([(219, 'Memory that grows with long-lived lists'), (220, 'Transforms that keep scrolling rows on the compositor')])))

# ---------------------------------------------------------------- 345 layout thrashing and CLS
T.append(topic(345, 'layout-thrashing-and-layout-shift', R, 25, 'Layout Thrashing and Layout Shift',
 ['Explain forced synchronous layout and why interleaved reads and writes are slow',
  'Batch DOM reads before writes',
  'Prevent layout shift by reserving space, and read a CLS score'],
 3, 11, [201, 210],
 [text(345, 1, 'Reading layout after a write forces work',
   'Browsers delay layout until they need it. If code changes a style and then asks for an element’s size or position, the browser must compute layout right away to answer. Doing that in a loop, write then read for each item, forces a layout per item: layout thrashing.',
   ['forced-layout']),
  text(345, 2, 'Worked example: 200 cards',
   'A script sets the width of 200 cards, reading each card’s height right after setting it. If one forced layout takes about 0.25 ms on this page (illustrative), 200 × 0.25 ms = 50 ms, three frames at 60 per second. Reading all 200 heights first, then setting all widths, needs one layout.',
   ['batching']),
  diagram(345, 3, 'Reads, then writes', 'Group by kind so the browser lays out once.', ['batching'],
   ['Read every measurement you need', 'Compute new values in memory', 'Write every style change', 'Let the browser lay out once before the next frame', 'Defer any further reads to the next frame']),
  text(345, 4, 'Layout shift is the user-visible cousin',
   'Cumulative Layout Shift measures content moving unexpectedly, such as text pushed down by an image or banner that loads late. A shift that affects half the viewport and moves content by a quarter of its height scores 0.5 × 0.25 = 0.125, above the 0.1 that counts as good. Reserving space for media, ads and embeds prevents most shifts.',
   ['cls']),
  text(345, 5, 'Trap: animating layout properties',
   'Animating width, height or top changes layout on every frame. Animating transform and opacity usually skips layout and paint, and shifts caused by transforms do not count towards CLS. Move things with transforms, not with layout properties.',
   ['cls', 'forced-layout'])],
 [mc('t345-a1', 'forced-layout', 'What forces the browser to compute layout immediately?',
   [('a', 'Changing a style and then reading a size or position'), ('b', 'Reading two sizes in a row with no changes'), ('c', 'Changing several styles with no reads between'), ('d', 'Loading a stylesheet in the head before any script runs')], 'a',
   'A read after a write needs up-to-date geometry, so layout runs at once.'),
  mc('t345-a2', 'batching', 'How should a loop that resizes 200 cards based on their heights be structured?',
   [('a', 'Write then read for each card in turn'), ('b', 'Spread the cards over 200 separate frames'), ('c', 'Read all heights first, then write all sizes'), ('d', 'Hide the cards while resizing them one by one')], 'c',
   'Batched reads then batched writes cost one layout instead of 200.'),
  mc('t345-a3', 'cls', 'A late ad pushes the article down. What prevents the shift?',
   [('a', 'Loading the ad sooner with a higher priority'), ('b', 'Reserving the ad’s space before it loads'), ('c', 'Fading the ad in slowly'), ('d', 'Showing the ad only after the user scrolls')], 'b',
   'If the space is already there, nothing moves when the ad arrives.'),
  mc('t345-a4', 'cls', 'Which change is least likely to add to CLS?',
   [('a', 'An image with no width and height loading late'), ('b', 'A web font swapping in with very different metrics'), ('c', 'A banner inserted above content after load'), ('d', 'A menu sliding in with a transform')], 'd',
   'Transform-based movement does not count as a layout shift.'),
  order('t345-a5', 'batching', 'Order one frame of a batched DOM update.',
   ['Read every measurement needed', 'Compute new values in memory', 'Write every style change', 'Let the browser lay out and paint once'],
   ['s2', 's4', 's3', 's1'], 'All reads, then computation, then all writes, then one layout.'),
  est('t345-a6', 'cls', 'A shift affects half the viewport and moves content by a quarter of the viewport height. What is its layout shift score?', 'score', 0.125,
   ['Impact fraction 0.5', 'Distance fraction 0.25'], 'impact fraction × distance fraction', '0.5 × 0.25 = 0.125',
   'Sanity check: one shift like this already exceeds the 0.1 “good” threshold.', 0.05, [0.75, 0.25])],
 flash(345, [('Layout thrashing?', 'Interleaved writes and reads forcing a layout each time.'),
             ('Fix it?', 'Batch all reads, then all writes.'),
             ('Good CLS?', '0.1 or less; reserve space and move things with transforms.')]),
 src([('web.dev: Avoid large, complex layouts and layout thrashing', 'https://web.dev/articles/avoid-large-complex-layouts-and-layout-thrashing'),
      ('web.dev: Cumulative Layout Shift (CLS)', 'https://web.dev/articles/cls')]),
 deep(['forced-layout', 'batching', 'cls'], 'Why the order of reads and writes matters',
  ['A frame runs script, then recalculates style, lays out boxes, paints and composites. The browser marks layout as dirty when styles change and normally recomputes it once, just before painting the next frame.',
   'Reading geometry, such as an element’s height, offset or scroll position, needs current layout. If layout is dirty, the browser must run style and layout immediately inside the script: a forced synchronous layout. In a loop that alternates writes and reads, each iteration dirties layout and then forces it again.',
   'Batching restores one layout per frame: perform all reads first, compute, then perform all writes. Reads can be cached between frames, and writes scheduled for just before the next frame. Smaller layout scopes, such as containment on independent components, also shrink the cost of each layout.',
   'Layout shift is a separate, user-visible problem. When content moves without user input, each shift is scored as impact fraction, the share of the viewport affected, times distance fraction, how far things moved relative to the viewport. Cumulative Layout Shift reports the largest burst of such shifts during the page’s life.',
   'Most shifts come from content arriving without reserved space: images and video without dimensions, ads and embeds, late banners, and web fonts with different metrics. Setting width and height or an aspect ratio, reserving slots, and inserting new content below the viewport or in response to user input avoid them. Shifts within half a second of a tap or key press are excluded from the score.'],
  ['Scripts that measure and then change many elements, such as masonry grids and auto-sizing text.', 'Pages with images, ads, embeds or late-loading banners.'],
  ['Avoid alternating style writes and geometry reads in loops.', 'Avoid animating width, height, top or left when a transform would do.'],
  ['Pattern', 'Layouts per frame', 'Effect'],
  [['Write, read, write, read', 'One per item', 'Long frames and jank'],
   ['All reads, then all writes', 'One', 'Smooth for the same work'],
   ['Transforms for movement', 'None for the movement', 'No layout and no layout shift']],
  'Cost of thrashing and of one shift',
  ['200 items updated in one loop', 'About 0.25 ms per forced layout (illustrative)', 'Shift affects 0.5 of the viewport and moves 0.25 of its height'],
  ['Interleaved: 200 × 0.25 ms = 50 ms of layout, about three 60 Hz frames.', 'Batched: one layout, about 0.25 ms.', 'Shift score: 0.5 × 0.25 = 0.125.', 'Good CLS is 0.1 or less, so this single shift fails it.'],
  'Batching turns a per-item cost into a per-frame cost; reserving space removes the shift entirely.',
  'Thresholds from the guidance', 'Official documentation',
  'web.dev defines Cumulative Layout Shift as a Core Web Vital, with 0.1 or less considered good and more than 0.25 poor, measured at the 75th percentile of page loads. Its guidance on layout thrashing explains that reading layout properties after changing styles forces synchronous layout, and recommends batching reads before writes.',
  [('“The loop is only 200 items, it can’t be slow.”', '“Interleaving forces 200 layouts; I’d read everything first, then write.”'),
   ('“The image loads fast, so no space is needed.”', '“I’d set its dimensions; any late load otherwise shifts the page.”')],
  ['A read after a write forces layout immediately.', 'Batch reads, then writes, for one layout per frame.', 'CLS is impact times distance; 0.1 or less is good.', 'Reserve space for late content and move things with transforms.']),
 {"kind": "slider", "title": "Interleaved or batched?", "prompt": "A loop updates some cards, reading each one’s height right after changing its width. Each forced layout costs about 0.25 ms here (illustrative) and a frame at 60 Hz has 16.7 ms. Slide the number of cards.",
  "model": "layout-thrash", "params": {"layoutMs": 0.25, "frameMs": 16.7},
  "control": {"label": "Cards updated", "min": 10, "max": 400, "step": 10, "initial": 200, "unit": ""},
  "takeaway": "Past about 66 cards the interleaved loop overruns a frame on layout alone; batching reads before writes keeps it to one layout."},
 see([(220, 'Compositor-only animation with transforms'), (216, 'How normal flow, flexbox and grid lay out boxes')])))

# ---------------------------------------------------------------- 346 workers and INP
T.append(topic(346, 'long-tasks-workers-and-inp', R, 26, 'Long Tasks, Web Workers and INP',
 ['Explain how a long task on the main thread delays input',
  'Split work into short tasks or move it to a worker',
  'Read INP thresholds and find what drives a poor score'],
 3, 12, [203, 210],
 [text(346, 1, 'One thread handles taps and your code',
   'The main thread runs scripts, handles input, and renders. While a task runs, a tap waits in the queue. A task longer than 50 ms counts as a long task, and a 400 ms task means a tap at its start waits 400 ms before any handler runs, and longer before the screen changes.',
   ['long-tasks']),
  text(346, 2, 'Worked example: filtering 50,000 rows',
   'Filtering and sorting 50,000 rows takes 400 ms on a mid-range phone (illustrative). Split into 50 ms pieces, 400 ÷ 50 gives 8 pieces, with input handled between them, so a tap waits at most about 50 ms. Moved to a worker, the main thread stays free and the tap is handled at once while the filter finishes elsewhere.',
   ['yielding', 'workers']),
  diagram(346, 3, 'Keeping input responsive', 'Shorten main-thread tasks or move them off it.', ['yielding', 'workers'],
   ['Find long tasks in a performance trace', 'Do the visible update first, defer the rest', 'Split remaining work into short chunks that yield', 'Move heavy computation to a worker and post results back', 'Measure INP from real users afterwards']),
  text(346, 4, 'What workers can and cannot do',
   'A web worker runs script on another thread with its own memory. It can compute, parse and fetch, but it cannot touch the page’s elements; it posts messages, which are copied, back to the main thread. Large data can be transferred rather than copied. Workers suit pure computation, not rendering.',
   ['workers']),
  text(346, 5, 'Trap: fast on your laptop',
   'A 60 ms task on a fast laptop can take several times longer on a budget phone. INP is judged at the 75th percentile of real visits, so test on slower devices or with CPU throttling, and watch field data rather than one local run.',
   ['inp'])],
 [mc('t346-a1', 'long-tasks', 'A 300 ms task starts just before a user taps a button. What happens to the tap?',
   [('a', 'It interrupts the running task and its handler runs first'), ('b', 'It waits until the task finishes before its handler runs'), ('c', 'It is dropped and must be repeated'), ('d', 'It runs in parallel on another thread')], 'b',
   'Input is queued behind the running task on the main thread.'),
  mc('t346-a2', 'workers', 'Which job suits a web worker best?',
   [('a', 'Parsing and sorting a large data file'), ('b', 'Changing the colour of a button on hover'), ('c', 'Measuring the height of a list item'), ('d', 'Moving focus to a dialog')], 'a',
   'Workers do computation; changes to page elements must happen on the main thread.'),
  mc('t346-a3', 'inp', 'Users say a dashboard feels sluggish after each click. Which delay does the responsiveness vital capture?',
   [('a', 'Time until the largest image or text block appears'), ('b', 'How far visible content moves while the page loads'), ('c', 'Script download time for the page'), ('d', 'Delay from an interaction to the next painted frame')], 'd',
   'INP covers input delay, handler time and rendering for interactions across the visit.'),
  mc('t346-a4', 'yielding', 'Why split a 400 ms task into 50 ms pieces that yield between them?',
   [('a', 'The total work finishes sooner because pieces are smaller'), ('b', 'The browser then runs pieces on several cores'), ('c', 'Input can be handled between pieces, so taps wait less'), ('d', 'Long tasks are blocked by the browser')], 'c',
   'Yielding lets queued input run; total time stays about the same.'),
  order('t346-a5', 'yielding', 'Order the response to a slow interaction.',
   ['Find the long task in a trace', 'Paint the visible feedback first', 'Split or move the remaining work', 'Confirm with field INP data'],
   ['s3', 's1', 's4', 's2'], 'Measure, give feedback quickly, fix the heavy part, then confirm with real users.'),
  est('t346-a6', 'yielding', 'A 400 ms task is split into 50 ms pieces. How many pieces is that?', 'pieces', 8,
   ['Pieces are equal length'], '400 ÷ 50', '400 ÷ 50 = 8 pieces',
   'Sanity check: the worst wait for a tap drops from about 400 ms to about 50 ms, while total work is unchanged.', 0, [50, 400])],
 flash(346, [('Long task?', 'A main-thread task over 50 ms; input waits behind it.'),
             ('Good INP?', '200 ms or less at the 75th percentile; over 500 ms is poor.'),
             ('Worker limits?', 'Own thread and memory, no access to page elements; talks by messages.')]),
 src([('web.dev: Interaction to Next Paint (INP)', 'https://web.dev/articles/inp'),
      ('MDN: Web Workers API', 'https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API')]),
 deep(['long-tasks', 'yielding', 'workers', 'inp'], 'How input waits and how to shorten the wait',
  ['The main thread runs one task at a time from its queues: script, input events, timers and rendering steps. A task is not interrupted when input arrives; the input event becomes a task that runs after the current one ends. Tasks over 50 ms are reported as long tasks.',
   'An interaction has three parts: input delay, waiting for the main thread to be free; processing time, running the handlers; and presentation delay, until the browser paints the next frame. Interaction to Next Paint reports roughly the slowest interaction of a visit, so one heavy handler can define the score.',
   'Yielding splits work so other tasks can run between pieces. The code does a chunk, schedules the rest as a new task, and returns; queued input runs in the gap. Total work is unchanged or slightly higher, but the longest wait shrinks to about one chunk.',
   'Workers move computation off the main thread. A dedicated worker has its own event loop and memory and communicates by posting messages, which are copied with the structured clone algorithm unless buffers are transferred. Workers cannot access page elements, so the main thread still applies results to the page.',
   'In handlers, update what the user sees first, such as a pressed state or spinner, and defer non-urgent work like analytics or saving. Reducing rendering cost, such as large layouts after an update, shortens the presentation part. Field data at the 75th percentile shows whether real users benefit.'],
  ['Pages with heavy parsing, filtering, sorting or formatting on interaction.', 'Apps targeting mid-range and low-end phones.'],
  ['Avoid workers for small tasks where message copying costs more than the work.', 'Avoid one long handler that updates the screen and does all background work in the same task.'],
  ['Approach', 'Worst input wait', 'Cost'],
  [['One long task', 'The whole task', 'Simple code, poor INP'],
   ['Split and yield', 'About one chunk', 'Slightly more total time, chunking logic'],
   ['Web worker', 'Near zero for that work', 'Message passing, no page access']],
  'How long a tap can wait',
  ['Filtering task of 400 ms on a mid-range phone (illustrative)', 'Chunks of 50 ms', 'Good INP is 200 ms or less'],
  ['One task: a tap at its start waits about 400 ms, past the 200 ms good threshold before any handler runs.', 'Split: 400 ÷ 50 gives 8 pieces; the worst wait is about 50 ms.', 'Worker: the main thread is free; the wait is set by other work only.', 'Total filter time stays about 400 ms in every case.'],
  'Splitting or moving work does not make it faster; it stops it from blocking input.',
  'Thresholds from the guidance', 'Official documentation',
  'web.dev defines Interaction to Next Paint as a Core Web Vital, with 200 ms or less considered good and more than 500 ms poor, measured at the 75th percentile of page loads. Its guidance on long tasks describes tasks longer than 50 ms as long tasks and recommends breaking them up and yielding to the main thread. MDN documents web workers as running scripts in background threads that communicate by messages.',
  [('“The filter is slow, so we need a faster algorithm.”', '“Maybe, but first I’d stop it blocking input by yielding or moving it to a worker.”'),
   ('“Workers can update the list directly.”', '“They can’t touch page elements; the worker computes and posts results back.”')],
  ['Input waits behind whatever task is running.', 'Long tasks are over 50 ms; good INP is 200 ms or less.', 'Split work and yield, or move computation to a worker.', 'Update visible feedback first and measure with field data.']),
 {"kind": "slider", "title": "How long does a tap wait?", "prompt": "A filter runs as one task on the main thread. Good INP is 200 ms or less, and the fix splits work into 50 ms pieces or moves it to a worker. Slide the task length.",
  "model": "long-task", "params": {"chunkMs": 50, "goodInpMs": 200},
  "control": {"label": "Task length", "min": 20, "max": 1000, "step": 10, "initial": 400, "unit": "ms"},
  "takeaway": "A single task over 200 ms fails the good INP threshold through input delay alone; split or moved, the worst wait stays near 50 ms whatever the task length."},
 see([(219, 'Long-lived pages where workers hold memory'), (211, 'Loading less script so the main thread is free sooner')])))
